new Derived();         ──►  super() (Base)  →  instance fields/initialisers  →  Derived() body
(no destructor)        ──►  object becomes unreachable → eligible for GC later

class Buffer {                       // owns an array → provide a copy constructor
    private int[] data;
    Buffer(int n) { data = new int[n]; }
    Buffer(Buffer o) { data = o.data.clone(); }    // deep copy of the backing array
    int[] view() { return data; }
}
